package main

import (
	_ "embed"
	"encoding/json"
	"log"

	"github.com/gin-gonic/gin"
)

// weapon_stats.json is generated by tools/weapon-stats/extract.py from the installed mods'
// prefabs (rate of fire, magazine, ballistics, damage-vs-range curve). Served as-is.
//
//go:embed weapon_stats.json
var weaponStatsRaw []byte

func getWeaponStats(c *gin.Context) {
	c.Header("Cache-Control", "public, max-age=3600")
	c.Data(200, "application/json; charset=utf-8", weaponStatsRaw)
}

func init() {
	if !json.Valid(weaponStatsRaw) {
		log.Println("weapon_stats.json: invalid JSON")
	}
}
